package at.andrew.squashtap;
import org.junit.Test;
import static org.junit.Assert.*;
import java.time.LocalDate;

public class PickleballTest {
    private MatchState match(boolean doubles,String rule){MatchState m=new MatchState("pickle-test",1,new MatchFormat("pickleball",doubles,11,rule,false));m.serving(0,1);return m;}
    @Test public void traditionalDoublesStartsWithSecondServerAndOnlyServingTeamScores(){MatchState m=match(true,"side-out");assertEquals("0–0–2",m.game().pickleCall());m.add(1);assertEquals(0,m.game().red());assertEquals(1,m.server());assertEquals(1,m.game().pickleServerNumber());m.add(0);assertEquals(3,m.server());m.add(0);assertEquals(0,m.server());assertEquals(1,m.game().pickleServerNumber());m.add(0);assertEquals(1,m.game().blue());assertEquals(0,m.server());m.add(1);assertEquals(2,m.server());assertEquals(2,m.game().pickleServerNumber());m.add(1);assertEquals(1,m.server());assertEquals(0,m.game().red());assertEquals(6,m.game().rallies());assertEquals(1,m.game().totalPoints(0));}
    @Test public void singlesSideOutRetainsRalliesWithoutInventingPoints(){MatchState m=match(false,"side-out");m.serving(1,0);m.add(0);assertEquals(0,m.game().blue());assertEquals(0,m.server());m.add(0);assertEquals(1,m.game().blue());m.undo();assertEquals(0,m.game().blue());assertEquals(0,m.server());m.undo();assertEquals(1,m.server());}
    @Test public void rally2025RequiresWinningServeBut2026AllowsReceiverToFinish(){for(String rule:new String[]{"rally-2025","rally-2026"}){MatchState m=match(true,rule);for(int i=0;i<10;i++)m.add(1);m.add(0);m.add(1);assertEquals(rule.equals("rally-2026"),m.complete());if(!m.complete()){assertEquals(10,m.game().red());m.add(1);assertTrue(m.complete());}assertEquals(1,m.winner());}}
    @Test public void rallyDoubleServerUsesRightPlayerAfterReceivingPoint(){MatchState m=match(true,"rally-2026");m.add(1);assertEquals(1,m.game().red());assertEquals(3,m.server());assertEquals("RIGHT",m.game().pickleCourt());m.add(0);assertEquals(1,m.game().blue());assertEquals(2,m.server());assertEquals(1,m.game().totalPoints(1));}
    @Test public void undoAndRestartRestoreFullServiceState(){MatchState m=match(true,"side-out");for(int side:new int[]{0,1,1,0,0,1,0,1})m.add(side);String saved=m.encode();MatchState copy=MatchState.decode(saved);assertEquals(saved,copy.encode());assertEquals(m.server(),copy.server());assertEquals(m.game().pickleCall(),copy.game().pickleCall());m.undo();copy.undo();assertEquals(m.encode(),copy.encode());}
    @Test public void serviceCannotReinterpretAlreadyRecordedRallies(){MatchState m=match(true,"side-out");m.add(0);String before=m.encode();assertThrows(IllegalArgumentException.class,()->m.serving(1,0));assertEquals(before,m.encode());m.undo();m.serving(3,2);assertEquals(3,m.server());}
    @Test public void nextGameAndEnteredUndoRetainChosenStarters(){MatchState m=new MatchState("pickle-next",3,MatchFormat.defaults("pickleball"));m.serving(2,3);m.enterCompletedSet(11,3);assertTrue(m.nextGame());assertEquals(3,m.server());m.enterCompletedSet(2,11);m.undo();assertEquals(3,m.server());assertEquals(m.encode(),MatchState.decode(m.encode()).encode());}
    @Test public void everyPickleballPresetRoundTripsBookAndCsv(){for(boolean doubles:new boolean[]{false,true})for(String rule:new String[]{"side-out","rally-2025","rally-2026"})for(int target:new int[]{11,15,21})for(int best:new int[]{1,3,5}){MatchFormat f=new MatchFormat("pickleball",doubles,target,rule,false);MatchBook b=new MatchBook(new MatchState("p-"+doubles+rule+target+best,best,f));b.add(0);b.retire(1);assertEquals(f,MatchBook.decode(b.encode()).current().format());assertEquals(f,MatchCsv.parse(MatchCsv.export(b.newestFirst(),new OpponentDirectory())).get(0).result.format);}}
    @Test public void nonScoringRallyStartsTimingAndDiscardLeavesNoResult(){MatchBook b=new MatchBook(match(true,"side-out"));b.add(1);assertTrue(b.currentStartedAt()>0);assertEquals(0,b.current().game().red());b.discardCurrent("new-empty");assertTrue(b.newestFirst().isEmpty());assertFalse(b.current().hasPoints());}
    @Test public void invalidRulesCannotMasqueradeAsAnotherSport(){assertThrows(IllegalArgumentException.class,()->new MatchFormat("tennis",false,11,"side-out",false));assertThrows(IllegalArgumentException.class,()->new MatchFormat("pickleball",true,9,"side-out",false));assertThrows(IllegalArgumentException.class,()->ScoreState.decode("3|pickleball,1,11,side-out,0|0|LBB"));}
    @Test public void presetsPreserveEveryRuleAndNames(){MatchPresets p=new MatchPresets();MatchPresets.Entry e=p.add("Freitag 🏓",new MatchFormat("pickleball",true,15,"rally-2025",false),1);MatchPresets q=MatchPresets.decode(p.encode());assertEquals(p.encode(),q.encode());assertEquals(0,q.list("tennis").size());q.remove(e.id);assertTrue(q.list(null).isEmpty());}
    @Test public void nativeActionTargetsAreAtLeast48dpOnEveryProfile(){for(float[] size:new float[][]{{180,180},{192,192},{216,216},{233,233},{240,240},{201,238}})for(int action:new int[]{TouchTargets.MENU,TouchTargets.UNDO,TouchTargets.NEW}){float[] r=TouchTargets.area(action,size[0],size[1]);assertTrue((r[2]-r[0])*size[0]>=47.99f);assertTrue((r[3]-r[1])*size[1]>=47.99f);assertEquals(action,TouchTargets.hit((r[0]+r[2])/2,(r[1]+r[3])/2,size[0],size[1]));}}
}
